/**
 * @file examples/validate/main.c
 * @brief Checkpoint-1: validate a baked-in SUIT envelope on RP2350.
 *
 * Demonstrates that the cross-built libsumo-onboard / libcsuit /
 * t_cose / QCBOR / pico-sdk-mbedtls stack actually verifies an
 * ES256-signed envelope on real hardware. No decryption, no
 * decompression, no fetch — just the signature + manifest digest
 * round trip.
 *
 * The fixture is generated by sumo-tool, signed with ES256:
 *
 *   sumo-tool keygen --algorithm es256 --output sign.key --public sign.pub
 *   sumo-tool build --signing-key sign.key \
 *     --component "ecu-a,firmware" --seq 1 \
 *     --vendor fa6b4a53d5ad5fdfbe9de663e4d41ffe \
 *     --class  1492af1425695e48bf429b2d51f2ab45 \
 *     --uri "file:///fw" \
 *     --payload-digest 00..00 --payload-size 100 \
 *     --output validate_fixture.suit
 *
 * SPDX-License-Identifier: Apache-2.0
 */
#include <stdio.h>
#include <string.h>

#include "pico/stdlib.h"
#include "psa/crypto.h"

#include "sumo/validator.h"

/* mbedtls_hardware_poll is supplied by pico-sdk's pico_mbedtls — we
 * link that target, so it's already wired to the silicon TRNG. */

/* --- Embedded fixture (sumo-tool output, see header comment) ------- */

