/* --- App entry ---------------------------------------------------- */

int main(void)
{
    stdio_init_all();
    sleep_ms(2000);  /* let the USB-CDC host enumerate */

    printf("\n--- sumo-rp2350 validate ---\n");

    psa_status_t ps = psa_crypto_init();
    if (ps != PSA_SUCCESS) {
        printf("psa_crypto_init FAILED (%d)\n", (int)ps);
        while (1) sleep_ms(1000);
    }
    printf("psa: ok\n");

    sumo_validator_t *v = sumo_validator_create(
        kTrustAnchor, sizeof(kTrustAnchor), NULL);
    if (!v) {
        printf("validator_create FAILED\n");
        while (1) sleep_ms(1000);
    }
    printf("validator: created with %zu-byte trust anchor\n",
           sizeof(kTrustAnchor));

    sumo_manifest_t *m = NULL;
    int rc = sumo_validate_envelope(v, kEnvelope, sizeof(kEnvelope), 0, &m);
    printf("validate: rc=%d (0=OK)\n", rc);

    if (rc == 0 && m) {
        printf("  sequence=%llu  components=%zu  campaign=%d\n",
               (unsigned long long)sumo_manifest_sequence_number(m),
               sumo_manifest_component_count(m),
               sumo_manifest_is_campaign(m));
        sumo_manifest_free(m);
    }
    sumo_validator_free(v);

    printf("idle.\n");
    while (1) sleep_ms(1000);
    return 0;
}
